<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Coupon;use App\Models\Plan;final class CouponController extends AdminController{public function index(Request $U):Response{return $this->view('admin/coupons',['coupons'=>Coupon::all('id','DESC'),'plans'=>Plan::all('sort'),'meta'=>['title'=>t('admin.coupons')]]);}public function save(Request $u):Response{if($a=$this->validate($u,['code'=>'required|max:64|regex:/^[A-Za-z0-9_-]+$/','kind'=>'required|in:percent,fixed','value'=>'required|numeric'],'/admin/coupons')){return $a;}$A=$u->int('id');$j=['code'=>strtoupper($u->str('code')),'kind'=>$u->str('kind'),'value'=>$u->str('kind')==='percent'?min(100,$u->int('value')):(int)round((float)str_replace(',','.',$u->str('value'))*100),'max_uses'=>$u->str('max_uses')===''?null:$u->int('max_uses'),'plan_slugs'=>array_values(array_filter((array)$u->input('plan_slugs',[]),'is_string')),'valid_from'=>$u->str('valid_from')?gmdate('Y-m-d 00:00:00',strtotime($u->str('valid_from'))?:time()):null,'valid_until'=>$u->str('valid_until')?gmdate('Y-m-d 23:59:59',strtotime($u->str('valid_until'))?:time()):null,'is_active'=>$u->bool('is_active')?1:0];$O=Coupon::findByCode($j['code']);if($O&&(int)$O['id']!==$A){$this->flash('error',t('admin.slug_taken'));return $this->redirect('/admin/coupons');}if($A){Coupon::update($A,$j);}else{$j['created_at']=now();Coupon::create($j);}AuditLog::log('admin.coupon_save',$j['code']);$this->flash('success',t('common.saved'));return $this->redirect('/admin/coupons');}public function delete(Request $P,string $q):Response{Coupon::delete((int)$q);AuditLog::log('admin.coupon_delete',$q);$this->flash('success',t('common.deleted'));return $this->redirect('/admin/coupons');}}